function twoSum(nums: number[], target: number): number[] {
const map = new Map();
for (let i = 0; i < nums.length; i ++) {
const current = nums[i];
const wanted = target - current;
if (map.has(wanted)) {
return [map.get(wanted), i]
}
map.set(current, i);
}
};
这种算法的思想就是基于一个注册表来查询匹配，返回匹配上的结果

function twoSum(nums: number[], target: number): number[] {
const n = nums.length;
for (let i = 0; i < n-1; i++) {
for (let j = i + 1; j < n; j++) {
if (nums[i] + nums[j] === target) {
return [i, j];
}
}
}
return [undefined, undefined];
}
注意，这里使用双指针，将所有可能得结果进行遍历，如果匹配则返回相对索引
还有就是遍历的边界问题
如果 i < n, j < n 也是可以的，越界后，无非就是数值 + undefined, 结果是NaN，这得益于javascript的弱类型语言
如果是其他强类型语言，就会报错，所以，需要特别注意下边界的问题

class SortedStack {
private stk1: number[] = [];
private stk2: number[] = [];
constructor() {}
// 插入元素时保持栈的排序
push(val: number): void {
// 将所有比 val 大的元素从 stk1 移动到 stk2
while (this.stk1.length > 0 && this.stk1[this.stk1.length - 1] < val) {
this.stk2.push(this.stk1.pop()!);
}
// 将新元素插入 stk1
this.stk1.push(val);
// 将 stk2 中的元素移回 stk1
while (this.stk2.length > 0) {
this.stk1.push(this.stk2.pop()!);
}
}
// 弹出栈顶元素
pop(): void {
if (!this.isEmpty()) {
this.stk1.pop();
}
}
// 获取栈顶元素
peek(): number {
if (this.isEmpty()) {
return -1;
} else {
return this.stk1[this.stk1.length - 1];
}
}
// 检查栈是否为空
isEmpty(): boolean {
return this.stk1.length === 0;
}
}
