function lengthOfLongestSubstring(s: string): number {
let l = 0;
let res = 0;
// 用于标记重复字符的字典结构
const map = new Map();
for(let r = 0; r < s.length; r++) {
if(map.has(s[r]) && map.get(s[r]) >= l) {
// 字典中存在
l = map.get(s[r]) + 1;
}
res = Math.max(res, r - l + 1);
map.set(s[r], r); // 字典更新最新的右指针
}
return res;
};
先找出所有不包含重复字符的子串，找出长度最大那个子串，返回其长度即可
用双指针维护一个滑动窗口，用来剪切子串
不断移动右指针，遇到重复字符，就把左指针移动到重复字符的下一位
在输入：“abcabcbb”
即左指针指向a(下标为0), 右指针指向c的时候，再移动一位, 右指针指向a(下标为3)的时候
左指针移动一位到b(下标为1)
移动过程中，记录所有窗口的长度，并返回最大值

function lengthOfLongestSubstring(s: string): number {
const len = s.length;
let max = 0;
for (let i = 0; i < len; i++) {
const set = new Set();
let maxLen = 0;
let j = i;
while (j < len && !set.has(s[j])) {
set.add(s[j]);
maxLen++;
j++;
}
max = Math.max(max, maxLen);
}
return max;
}
使用set集合来确定字符串的连续型，并暴力枚举各种符合情况
这种算法不推荐

class Automaton {
private state: string = "start";
private table: { [key: string]: string[] } = {
"start": ["start", "signed", "in_number", "end"],
"signed": ["end", "end", "in_number", "end"],
"in_number": ["end", "end", "in_number", "end"],
"end": ["end", "end", "end", "end"]
};
public sign: number = 1;
public ans: number = 0;
private get_col(c: string): number {
if (c === ' ') return 0;
if (c === '+' || c === '-') return 1;
if (!isNaN(parseInt(c, 10))) return 2;
return 3;
}
public get(c: string): void {
this.state = this.table[this.state][this.get_col(c)];
if (this.state === "in_number") {
this.ans = this.ans * 10 + parseInt(c, 10);
// 检查是否超出32位有符号整数范围
if (this.sign === 1) {
this.ans = Math.min(this.ans, 2147483647); // INT_MAX
} else {
this.ans = Math.min(this.ans, 2147483648); // -INT_MIN
}
} else if (this.state === "signed") {
this.sign = c === '+' ? 1 : -1;
}
}
}
function myAtoi(str: string): number {
const automaton = new Automaton();
for (const c of str) {
automaton.get(c);
}
return automaton.sign * automaton.ans;
}

function myAtoi(s: string): number {
let res = 0;
const bndry = Math.floor(Number.MAX_SAFE_INTEGER / 10);
let i = 0;
let sign = 1;
const length = s.length;
if (length === 0) return 0;
// Skip leading whitespace
while (s.charCodeAt(i) === 32) {
if (++i === length) return 0;
}
// Handle sign
if (s.charCodeAt(i) === 45) {
sign = -1;
} else if (s.charCodeAt(i) === 43) {
// Do nothing for positive sign
}
if (s.charCodeAt(i) === 45 || s.charCodeAt(i) === 43) {
i++;
}
// Process digits
for (let j = i; j < length; j++) {
const charCode = s.charCodeAt(j);
if (charCode < 48 || charCode > 57) {
break;
}
const digit = charCode - 48;
if (res > bndry || (res === bndry && digit > 7)) {
return sign === 1 ? Number.MAX_SAFE_INTEGER : Number.MIN_SAFE_INTEGER;
}
res = res * 10 + digit;
}
return sign * res;
}
这个方案有精度问题
对大部分case都可以通过
