function letterCombinations(digits: string): string[] {
// 对输入做处理，如果小于1返回空
if (digits.length < 1) return []
// 建立电话号码键盘字典映射
const dict: string[] = ['', '', 'abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz']
// 如果只给了一个按键，直接把按键内容取出来并按单个字符分组
if (digits.length < 2) return dict[digits].split('')
// 把输入字符串按单字符分隔变成数组，234 => [2,3,4]
const num: string[] = digits.split('')
// 保存键盘映射后的字母内容，如 23 => ['abc','def']
const code: string[] = []
num.forEach(item => {
if (!dict[item]) return
code.push(dict[item])
})
// 这里arr可以是数组和字符串的集合
const comb = (arr: any[]) => {
// 临时变量用来保存前两个组合的结果
const tmp: string[] = []
// 最外层的循环是遍历第一个元素，里层的循环是遍历第二个元素
for (let i = 0, ilen = arr[0].length; i < ilen; i++) {
for (let j = 0, jlen = arr[1].length; j < jlen; j++) {
tmp.push(`${arr[0][i]}${arr[1][j]}`)
}
}
// 从数组中索引为0开始删除，一共删除2个元素，将arr数组的前两项用 tmp 数组替代
arr.splice(0, 2, tmp)
if (arr.length > 1) {
comb(arr)
// 这是递归后形成的最后一个结果数组进行返回，这个数组只有一个元素
return arr[0]
}
return tmp
}
return comb(code)
};
按照题目要求，可以任意输入符合要求的数值型字符串来获取最终的组合结果
我们并不知道用户会输入多少字符，比如：2,3；2,3,4；2,3,4,5；2,3,4,5,6,…
所以并不适合使用n层循环来暴力枚举，需要的是两两组合
两两组合完事后，将前两个替换成最新的一个来与后面的一个再次进行两两组合
直到最终只有一个数组的时候结束，这里用的递归的思路来处理的
同时，我们字符串和数组都可以按下标来进行访问，这一点要注意
这里一个重要的数组api是 splice，即这行：arr.splice(0, 2, tmp)
这里arr是个any[]类型的数组，里面的数据结构是字符串和数组混合结构的数组
这里考察的是组合关系
这个dict字典的设计是比较合适的，前两个都是'', 为了和数字与下标的转换进行匹配
但是重新审视这个算法，两个for循环嵌套，还是递归，这里时间复杂度较高
时间复杂度为 O(N + N + N + log(N) * K * L^2)
其中 N 为输入字符串长度，K 为有效按键数量，L 为按键平均长度
空间复杂度为 O(N + N + K * L + log(N) * K * L)
构建了 num 数组和 code 数组，它们各自的空间复杂度为 O(N)
递归调用时，使用了 tmp 临时数组，其空间复杂度为 O(K * L)，其中 K 为数组长度，L 为数组平均长度
递归调用的层数为 log(N)，每层都有一个 tmp 数组，因此总体递归的空间复杂度为 O(log(N) * K * L)

// 定义 letterCombinations 方法，接收一个字符串参数 digits，返回一个字符串数组
function letterCombinations(digits: string): string[] {
// 如果 digits 为空字符串，直接返回空数组
if (!digits) return [];
// 定义电话号码对应的字母组合映射
const phoneMap: { [key: string]: string } = {
"2": "abc",
"3": "def",
"4": "ghi",
"5": "jkl",
"6": "mno",
"7": "pqrs",
"8": "tuv",
"9": "wxyz",
};
// 定义回溯函数，接收一个索引参数
const backtrack = (index: number): void => {
// 如果索引等于 digits 的长度，将当前组合加入结果数组
if (index === digits.length) {
combinations.push(combination.join(''));
} else {
// 获取当前数字对应的字母组合
const digit = digits[index];
// 遍历当前数字对应的字母组合
for (const letter of phoneMap[digit]) {
// 将当前字母加入组合
combination.push(letter);
// 递归调用回溯函数，增加索引
backtrack(index + 1);
// 回溯，将最后加入的字母移除，尝试其他字母
combination.pop();
}
}
};
// 初始化组合和结果数组
const combination: string[] = [];
const combinations: string[] = [];
// 调用回溯函数，从索引 0 开始
backtrack(0);
// 返回最终的结果数组
return combinations;
}
使用哈希表存储每个数字对应的所有可能的字母，然后进行回溯操作
回溯过程中维护一个字符串，表示已有的字母排列
如果未遍历完电话号码的所有数字，则已有的字母排列是不完整的
该字符串初始为空。每次取电话号码的一位数字
从哈希表中获得该数字对应的所有可能的字母，并将其中的一个字母插入到已有的字母排列后面
然后继续处理电话号码的后一位数字，直到处理完电话号码中的所有数字
即得到一个完整的字母排列。然后进行回退操作，遍历其余的字母排列
回溯算法用于寻找所有的可行解，如果发现一个解不可行，则会舍弃不可行的解
在这道题中，由于每个数字对应的每个字母都可能进入字母组合，因此不存在不可行的解，直接穷举所有的解即可
时间复杂度：O(3m×4n3^m×4^n)
空间复杂度: O(m + n) 线性
m 是对应三个字母的数字个数，n 是对应四个字母的数字个数

// 定义 letterCombinations 方法，接收一个字符串参数 digits，返回一个字符串数组
function letterCombinations(digits: string): string[] {
// 如果 digits 为空字符串，直接返回空数组
if (!digits) return [];
// 定义电话号码对应的字母组合数组
const phone: string[] = ['abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz'];
// 初始化队列，将空字符串作为初始元素
let queue: string[] = [''];
// 遍历输入的数字字符串
for (const digit of digits) {
// 获取当前队列的长度
const queueLength = queue.length;
// 遍历当前队列中的元素
for (let i = 0; i < queueLength; i++) {
// 从队列中取出一个元素
const tmp = queue.shift()!;
// 遍历当前数字对应的字母组合, 这里字符串 2 的 Unicode 编码是 50, 减去后对应上述数组的索引
for (const letter of phone[digit.charCodeAt(0) - 50]) {
// 将当前元素和字母组合的每个字母拼接，然后加入队列
queue.push(tmp + letter);
}
}
}
// 返回最终的结果数组
return queue;
}
使用队列，先将输入的 digits 中第一个数字对应的每一个字母入队
然后将出队的元素与第二个数字对应的每一个字母组合后入队…直到遍历到 digits 的结尾
最后队列中的元素就是所求结果
