/**
* Definition for singly-linked list.
* class ListNode {
* val: number
* next: ListNode | null
* constructor(val?: number, next?: ListNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.next = (next===undefined ? null : next)
* }
* }
*/
class Status {
val: number;
ptr: ListNode;
constructor(val: number, ptr: ListNode) {
this.val = val;
this.ptr = ptr;
}
}
class PQ<T> {
private heap: T[];
constructor() {
this.heap = [];
}
get length(): number {
return this.heap.length;
}
private compare(a: T, b: T): number {
if (a instanceof Status && b instanceof Status) {
return a.val - b.val;
}
throw new Error('Invalid comparison types');
}
push(item: T): void {
this.heap.push(item);
this._siftUp(this.heap.length - 1);
}
pop(): T | undefined {
if (this.heap.length === 0) return undefined;
const lastElement = this.heap.pop();
if (this.heap.length === 0) return lastElement;
const returnItem = this.heap[0];
this.heap[0] = lastElement!;
this._siftDown(0);
return returnItem;
}
private _siftUp(index: number): void {
while (index > 0) {
const parentIndex = Math.floor((index - 1) / 2);
if (this.compare(this.heap[parentIndex], this.heap[index]) > 0) {
[this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];
index = parentIndex;
} else {
break;
}
}
}
private _siftDown(index: number): void {
const size = this.heap.length;
while (true) {
let smallest = index;
const leftChild = 2 * index + 1;
const rightChild = 2 * index + 2;
if (leftChild < size && this.compare(this.heap[leftChild], this.heap[smallest]) < 0) {
smallest = leftChild;
}
if (rightChild < size && this.compare(this.heap[rightChild], this.heap[smallest]) < 0) {
smallest = rightChild;
}
if (smallest !== index) {
[this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
index = smallest;
} else {
break;
}
}
}
}
function mergeKLists(lists: Array<ListNode | null>): ListNode | null {
const queue = new PQ<Status>();
for (const node of lists) {
if (node !== null) {
queue.push(new Status(node.val, node));
}
}
const head = new ListNode(0);
let tail = head;
while (queue.length > 0) {
const f = queue.pop();
if (f) {
tail.next = f.ptr;
tail = tail.next;
if (f.ptr.next !== null) {
queue.push(new Status(f.ptr.next.val, f.ptr.next));
}
}
}
return head.next;
}

