function firstMissingPositive(nums: number[]): number {
const n: number = nums.length;
const { abs } = Math;
let i: number;
// 第一轮循环将所有的非正整数都修改成 n + 1, 这时候 数组内都是正整数了，方便加负号标记了
for (let i = 0; i < n; ++i) {
if (nums[i] <= 0) nums[i] = n + 1;
}
// 第二轮循环将当前元素中 1 ~ n 之内的数对应的位置上的值修改成负值，这样就标记了该位置表示的值(下标)已经出现过了
for (i = 0; i < n; ++i) {
let num = abs(nums[i]); // 拿到当前下标对应的元素的绝对值
if (num <= n) nums[num - 1] = -abs(nums[num - 1]);
}
// 最后一轮遍历是找数组中仍是正数的下标，该下标所在的位置就是所求
for (i = 0; i < n; ++i) {
if (nums[i] > 0) return i + 1;
}
// 以上运算都找不到正数，则都已经标记为负数，直接返回 n + 1
return n + 1;
}
官方提供方法
首次缺失的正数，一定在 [1, N + 1]范围内
数组本身有索引, 而每个索引都有对应的元素, 将数组的索引当做哈希的键值
在对应元素上添加特殊符号(负号)，来标记该位数字是否存在，负号表示存在
比如1出现了，把第一个元素变成负数，2出现了，把第二个元素(索引值为1的元素)变成负数
只要一个数字出现，它对应的第几个元素就标记为负数
只要返回第一个正数的位置，就是缺失的第一个正数
时间复杂度：O(N)，其中 N 是数组的长度
空间复杂度：O(1)

function firstMissingPositive(nums: number[]): number {
const n: number = nums.length;
let i: number;
// 第一轮遍历
for (i = 0; i < n; ++i) {
// 如果当前元素在 0 ~ n 之间, 当前元素 和 当前元素对应的位置 - 1 (下标) 不一致 则进行交换
while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
[nums[nums[i] - 1], nums[i]] = [nums[i], nums[nums[i] - 1]]; // 交换
}
}
// 第二轮遍历，找到第一个当前值与当前位置不匹配时的位置(备注: 位置比下标大1)
for (i = 0; i < n; ++i) {
if (nums[i] != i + 1) {
return i + 1;
}
}
return n + 1;
}
这是官方提供
将正确的元素放在正确的位置上，寻找第一个值与下标不匹配的元素
如果数组中包含 x∈[1,N]，那么恢复后，数组的第 x−1 个元素为 x
在恢复后，数组应当有 [1, 2, …, N] 的形式，但其中有若干个位置上的数是错误的，每一个错误的位置就代表了一个缺失的正数
以题目中的示例二 [3, 4, -1, 1] 为例，恢复后的数组应当为 [1, -1, 3, 4]，我们就可以知道缺失的数为 2
时间复杂度：O(N)，其中 N 是数组的长度
空间复杂度：O(1)

function multiply(num1: string, num2: string): string {
if (num1 === "0" || num2 === "0") return "0";
let ans = "0";
const m = num1.length;
const n = num2.length;
for (let i = n - 1; i >= 0; i--) {
let curr = "";
let carry = 0;
// 添加适当的零位
for (let j = n - 1; j > i; j--) {
curr += "0";
}
const y = parseInt(num2.charAt(i), 10);
for (let j = m - 1; j >= 0; j--) {
const x = parseInt(num1.charAt(j), 10);
const product = x * y + carry;
curr = (product % 10).toString() + curr;
carry = Math.floor(product / 10);
}
while (carry !== 0) {
curr = (carry % 10).toString() + curr;
carry = Math.floor(carry / 10);
}
ans = addStrings(ans, curr);
}
return ans;
}
function addStrings(num1: string, num2: string): string {
let i = num1.length - 1;
let j = num2.length - 1;
let carry = 0;
let result = "";
while (i >= 0 || j >= 0 || carry !== 0) {
const x = i >= 0 ? parseInt(num1.charAt(i), 10) : 0;
const y = j >= 0 ? parseInt(num2.charAt(j), 10) : 0;
const sum = x + y + carry;
result = (sum % 10).toString() + result;
carry = Math.floor(sum / 10);
i--;
j--;
}
return result;
}

function multiply(num1: string, num2: string): string {
if (num1 === "0" || num2 === "0") return "0";
const m = num1.length;
const n = num2.length;
const ansArr: number[] = new Array(m + n).fill(0);
// 计算每一位的乘积并累加到 ansArr 中
for (let i = m - 1; i >= 0; i--) {
const x = parseInt(num1.charAt(i), 10);
for (let j = n - 1; j >= 0; j--) {
const y = parseInt(num2.charAt(j), 10);
ansArr[i + j + 1] += x * y;
}
}
// 处理进位
for (let i = m + n - 1; i > 0; i--) {
ansArr[i - 1] += Math.floor(ansArr[i] / 10);
ansArr[i] %= 10;
}
// 构建最终结果字符串
let ans = "";
let idx = 0;
if (ansArr[0] === 0) {
idx = 1;
}
for (; idx < m + n; idx++) {
ans += ansArr[idx].toString();
}
return ans;
}
