function solveNQueens(n: number): string[][] {
const solutions = [];
const queens = new Array(n).fill(-1);
const columns = new Set();
const diagonal1 = new Set();
const diagonal2 = new Set();
const row = new Array(n).fill(".");
function generateBoard() {
const board = [];
for (let i = 0; i < n; i++) {
row[queens[i]] = "Q";
board.push(row.join(""));
row[queens[i]] = ".";
}
return board;
}
function backtrack(row) {
if (row === n) {
const board = generateBoard();
solutions.push(board);
} else {
for (let i = 0; i < n; i++) {
if (columns.has(i) || diagonal1.has(row - i) || diagonal2.has(row + i)) {
continue;
}
queens[row] = i;
columns.add(i);
diagonal1.add(row - i);
diagonal2.add(row + i);
backtrack(row + 1);
columns.delete(i);
diagonal1.delete(row - i);
diagonal2.delete(row + i);
}
}
}
backtrack(0);
return solutions;
};

function solveNQueens(n: number): string[][] {
const solutions = [];
const queens = new Array(n).fill(-1);
const row = new Array(n).fill(".");
function generateBoard() {
const board = [];
for (let i = 0; i < n; i++) {
row[queens[i]] = "Q";
board.push(row.join(""));
row[queens[i]] = ".";
}
return board;
}
function solve(row, columns, diagonals1, diagonals2) {
if (row === n) {
const board = generateBoard();
solutions.push(board);
} else {
let availablePositions = ((1 << n) - 1) & (~(columns | diagonals1 | diagonals2));
while (availablePositions) {
const position = availablePositions & -availablePositions;
availablePositions &= availablePositions - 1;
const column = Math.log2(position);
queens[row] = column;
solve(row + 1, columns | position, (diagonals1 | position) << 1, (diagonals2 | position) >> 1);
}
}
}
solve(0, 0, 0, 0);
return solutions;
};

function solveNQueens(n: number): string[][] {
// [1,3,0,2]
const ret = []
const path = []
function backtrack(row, tmp) {
if (row === n) {
ret.push(
tmp.map(c => {
let arr = new Array(n).fill('.')
arr[c] = 'Q'
return arr.join('')
})
)
}
// row 第几行
for (let col = 0; col < n; col++) {
let canNotSet = tmp.some((c, r) => {
return c == col || ((r - c) === (row - col)) || ((r + c) === (row + col))
})
if (canNotSet) {
continue
}
backtrack(row + 1, [...tmp, col])
}
}
// r c row col
// r==row c==col r-c==row-col r+c row+col
backtrack(0, path)
return ret
};
