function uniquePaths(m: number, n: number): number {
// 计算组合数 C(m+n-2, m-1) 或 C(m+n-2, n-1)
// 选择较小的那个计算以减少循环次数
const k = Math.min(m - 1, n - 1);
let result = 1;
for (let i = 1; i <= k; i++) {
result *= (m + n - 1 - i);
result = Math.floor(result / i); // 确保每一步都是整数除法
}
return result;
}

function uniquePaths(m: number, n: number): number {
