let l = 0, r = x, ans = -1;
while (l <= r) {
let mid = l + Math.floor((r - l) / 2);
if (mid * mid <= x) {
ans = mid;
l = mid + 1;
} else {
r = mid - 1;
}
}
return ans;
}

function mySqrt(x: number): number {
let left = 0
let right = x
while (left <= right) {
let mid = left + ((right - left) >> 1)
if (mid * mid < x) {
left = mid + 1
} else if (mid * mid > x) {
right = mid - 1
} else if (mid * mid === x) {
return mid
}
}
return left - 1
};

