function sortColors(nums: number[]): void {
const n: number = nums.length;
let ptr: number = 0;
// First pass: Move all 0s to the beginning
for (let i = 0; i < n; ++i) {
if (nums[i] === 0) {
const temp: number = nums[i];
nums[i] = nums[ptr];
nums[ptr] = temp;
++ptr;
}
}
// Second pass: Move all 1s to the positions after 0s
for (let i = ptr; i < n; ++i) {
if (nums[i] === 1) {
const temp: number = nums[i];
nums[i] = nums[ptr];
nums[ptr] = temp;
++ptr;
}
}
}

