function sortColors(nums: number[]): void {
const n: number = nums.length;
let p0: number = 0;
let p1: number = 0;
for (let i = 0; i < n; ++i) {
if (nums[i] === 1) {
// Swap nums[i] with nums[p1]
const temp: number = nums[i];
nums[i] = nums[p1];
nums[p1] = temp;
++p1;
} else if (nums[i] === 0) {
// Swap nums[i] with nums[p0]
const temp: number = nums[i];
nums[i] = nums[p0];
nums[p0] = temp;
// If p0 is less than p1, swap nums[i] with nums[p1]
if (p0 < p1) {
const temp2: number = nums[i];
nums[i] = nums[p1];
nums[p1] = temp2;
}
++p0;
++p1;
}
}
}

/**
Do not return anything, modify nums in-place instead.
*/
function sortColors(nums: number[]): void {
const n: number = nums.length;
let p0: number = 0;
let p2: number = n - 1;
for (let i = 0; i <= p2; ++i) {
// 处理 nums[i] == 2 的情况
while (i <= p2 && nums[i] === 2) {
const temp: number = nums[i];
nums[i] = nums[p2];
nums[p2] = temp;
--p2;
}
// 处理 nums[i] == 0 的情况
if (nums[i] === 0) {
const temp: number = nums[i];
nums[i] = nums[p0];
nums[p0] = temp;
++p0;
}
}
}
