function minWindow(s: string, t: string): string {
let l = 0;
let r = 0;
// 维护一个字典，表示子串需要的字符(键)以及长度(值)
const m = new Map();
// 遍历模板字符串t 用字典存储
for(let c of t) {
// 这样遍历，可以包含模板字符串t中存在重复的字符
m.set(c, m.has(c) ? m.get(c) + 1 : 1);
}
// 哨兵变量 mSize 用于存储字典中字符的长度
let mSize = m.size;
// 用于存储输出结果
let res = '';
while(r < s.length) {
let c = s[r];
// 如果字典中有该值，那么字典中就不需要了
if (m.has(c)) {
// 比如s中遇到了A, 在m中有A, 那么在m中A就不再需要了
// 如果模板字符串t中含有多个A, 那么此处减少一个A
m.set(c, m.get(c) - 1);
// 字典中相关字符已经用完
if(!m.get(c)) {
mSize--;
}
}
// 此处监听mSize是否全部用完
while(!mSize) {
const newRes = s.substring(l, r + 1);
if(!res || newRes.length < res.length) {
res = newRes;
}
// 拿到左指针
let c2 = s[l];
if(m.has(c2)) {
m.set(c2, m.get(c2) + 1);
if(m.get(c2) === 1) {
mSize ++;
}
}
l++; // 左指针移动
}
r++; // 右指针移动
}
return res;
}
