const ret = []
const path = [] //递归的时候用的临时，用来统计[2]
function backtrack(n, k, i) {
let len = path.length
if (len === k) {
ret.push([...path])
return
}
// n=4，k=2 i = 1 len = 0
// 1,2,3 选4，后面就没了
for (let j = i; j <= n - k + len + 1; j++) {
path.push(j)
backtrack(n, k, j + 1)
path.pop()
}
}
backtrack(n, k, 1)
return ret
