function exist(board: string[][], word: string): boolean {
const h = board.length, w = board[0].length;
const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
const visited = new Array(h);
for (let i = 0; i < visited.length; ++i) {
visited[i] = new Array(w).fill(false);
}
const check = (i, j, s, k) => {
if (board[i][j] != s.charAt(k)) {
return false;
} else if (k == s.length - 1) {
return true;
}
visited[i][j] = true;
let result = false;
for (const [dx, dy] of directions) {
let newi = i + dx, newj = j + dy;
if (newi >= 0 && newi < h && newj >= 0 && newj < w) {
if (!visited[newi][newj]) {
const flag = check(newi, newj, s, k + 1);
if (flag) {
result = true;
break;
}
}
}
}
visited[i][j] = false;
return result;
}
for (let i = 0; i < h; i++) {
for (let j = 0; j < w; j++) {
const flag = check(i, j, word, 0);
if (flag) {
return true;
}
}
}
return false;
};

function grayCode(n: number): number[] {
// 初始化n为1位时的场景
const result = [0, 1]
// 对n位进行遍历
for (let i = 1; i < n; i++) {
const len = result.length
// 倒序循环，内层循环一次完毕，会递增len的长度，也就是让result中的元素翻一倍
for (let j = len - 1; j >= 0; j--) {
// 进行左移操作，并加入当前的值
result.push((1 << i) + result[j])
}
}
return result
};
这是官方示例，两个for循环，内部使用了左移操作
这个算法很精妙，比方案1好很多，而且效率也较高
这种算法策略利用了格雷编码的特性
相邻两个格雷码之间只有一位二进制位不同
通过对当前已有的格雷编码序列进行左移操作
并在前面加上新的二进制位（0 或 1）, 可以得到新的格雷编码序列
而通过在内层循环中倒序遍历已有的格雷编码序列
并在每个元素前加上左移操作得到的新值
可以保证生成的新格雷编码序列满足相邻两个格雷码之间只有一位不同的条件

function grayCode(n: number): number[] {
// 初始化结果数组，初始值为 0
const ret: number[] = [0];
// 遍历生成长度为 n 的格雷编码序列
for (let i = 1; i <= n; i++) {
// 获取当前结果数组的长度
const m = ret.length;
// 从后往前遍历已有的格雷编码序列
for (let j = m - 1; j >= 0; j--) {
// 在已有的格雷编码基础上进行位运算，生成新的格雷编码，并添加到结果数组中
ret.push(ret[j] | (1 << (i - 1)));
}
}
return ret; // 返回生成的格雷编码序列数组
};
初始化结果数组：首先，创建一个数组 ret，并将初始值 0 放入其中。这是因为格雷编码序列的起始值总是 0
遍历生成格雷编码序列：使用一个循环来生成长度为 n 的格雷编码序列。从 1 开始遍历，直到 n
遍历已有的格雷编码：在每次迭代中，通过遍历已有的格雷编码来生成新的格雷编码
从已有的格雷编码数组的最后一个元素开始，向前遍历直到第一个元素
位运算生成新的格雷编码：在内部循环中，对已有的格雷编码进行位运算来生成新的格雷编码
具体来说，通过按位或运算将 1 左移 (i - 1) 位后，与已有的格雷编码进行按位或操作，生成新的格雷编码
将新的格雷编码添加到结果数组：将生成的新格雷编码添加到结果数组中
返回结果数组：最后，返回生成的格雷编码序列数组 ret

function grayCode(n: number): number[] {
// 初始化结果数组
const ret: number[] = [];
// 遍历生成格雷编码序列
for (let i = 0; i < 1 << n; i++) {
// 根据格雷编码生成规则，将当前数值添加到结果数组中
ret.push((i >> 1) ^ i);
}
return ret; // 返回生成的格雷编码序列数组
}
遍历所有可能的格雷编码
通过循环遍历 0 到 2^n - 1 的所有数值，其中 n 是格雷编码序列的长度
这保证了所有可能的格雷编码都被生成
位运算生成格雷编码：对于每个数值 i，通过位运算生成相应的格雷编码 grayCode(i) = (i >> 1) ^ i
这里 >> 是右移位操作，^ 是异或操作
这个公式的实现效果是将当前数值右移一位，然后与原始数值进行异或操作，从而生成对应的格雷编码
添加到结果数组：将生成的格雷编码依次添加到结果数组中

/**
* Definition for singly-linked list.
* class ListNode {
* val: number
* next: ListNode | null
* constructor(val?: number, next?: ListNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.next = (next===undefined ? null : next)
* }
* }
*/
const reverseLinkedList = (head: ListNode | null) => {
let pre = null;
let cur = head;
while (cur) {
const next = cur.next;
cur.next = pre;
pre = cur;
cur = next;
}
}
function reverseBetween(head: ListNode | null, left: number, right: number): ListNode | null {
// 因为头节点有可能发生变化，使用虚拟头节点可以避免复杂的分类讨论
const dummyNode = new ListNode(-1);
dummyNode.next = head;
let pre = dummyNode;
// 第 1 步：从虚拟头节点走 left - 1 步，来到 left 节点的前一个节点
// 建议写在 for 循环里，语义清晰
for (let i = 0; i < left - 1; i++) {
pre = pre.next;
}
// 第 2 步：从 pre 再走 right - left + 1 步，来到 right 节点
let rightNode = pre;
for (let i = 0; i < right - left + 1; i++) {
rightNode = rightNode.next;
}
// 第 3 步：切断出一个子链表（截取链表）
let leftNode = pre.next;
let curr = rightNode.next;
// 注意：切断链接
pre.next = null;
rightNode.next = null;
// 第 4 步：同第 206 题，反转链表的子区间
reverseLinkedList(leftNode);
// 第 5 步：接回到原来的链表中
pre.next = rightNode;
leftNode.next = curr;
return dummyNode.next;
};

/**
* Definition for singly-linked list.
* class ListNode {
* val: number
* next: ListNode | null
* constructor(val?: number, next?: ListNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.next = (next===undefined ? null : next)
* }
* }
*/
function reverseBetween(head: ListNode | null, left: number, right: number): ListNode | null {
// 设置 dummyNode 是这一类问题的一般做法
const dummy_node = new ListNode(-1);
dummy_node.next = head;
let pre = dummy_node;
for (let i = 0; i < left - 1; ++i) {
pre = pre.next;
}
let cur = pre.next;
for (let i = 0; i < right - left; ++i) {
const next = cur.next;
cur.next = next.next;
next.next = pre.next;
pre.next = next;
}
return dummy_node.next;
};

function restoreIpAddresses(s: string): string[] {
// 处理异常输入
if (s.length > 12) return [];
// 保存所有符合条件的IP地址
const result: string[] = [];
// 递归处理ip分段
const searchFn = (cur: number[], sub: string) => {
// 匹配时，当前有4项，并且整体字符长度和输入一致
if (cur.length === 4 && cur.join('') === s) {
result.push(cur.join('.'));
return;
}
// 正常的处理过程，注意 len 最多为 3
for (let i = 0, len = Math.min(3, sub.length), tmp: number; i < len; i++) {
tmp = Number(sub.substring(0, i + 1)); // 逐位开始获取字符串
// 如果tmp合法，满足一位的条件，则继续进行下一位的处理
if (tmp < 256) {
// 继续下一位的递归
searchFn(cur.concat([tmp]), sub.substring(i + 1));
}
}
}
// 递归开始
searchFn([], s);
return result;
}
该题目是ip地址相关，ip地址的特征是 4块，通过 . 来分隔
也就是由3个 . 分成4部分
每一部分可能是 3位，2位，1位
每一部分的范围是 0 ~ 255
总体长度不会超过 12
先找第一部分，再找第二部分…, 直到最后一部分
4部分加在一起的总长度和输入长度相同，则找到的这个是正确的
每一次尝试的时候，如果走不通，就回到上一步，这个也是回溯的核心
