/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function isValidBST(root: TreeNode | null): boolean {
// 1. 声明最终存储树的数组
const traversalArr: number[] = [];
// 2. 定义基于中序遍历获取最终数组算法
function inorderTraverse(root: TreeNode | null): void {
if (!root) return;
inorderTraverse(root.left);
traversalArr.push(root.val);
inorderTraverse(root.right);
}
// 3. 开始中序遍历
inorderTraverse(root);
// 4. 验证当前数组是否符合要求
for (let i = 0, length = traversalArr.length; i < length - 1; i++) {
if (traversalArr[i] >= traversalArr[i + 1]) return false;
}
return true;
};
此方案是官方提供算法，用到了中序遍历的特性，它先遍历左子树，再遍历根节点，最后遍历右子树
而我们二叉搜索树保证了左子树的节点的值均小于根节点的值，根节点的值均小于右子树的值
因此中序遍历以后得到的序列一定是升序序列
最终进行验证的for循环就是检验是否是升序序列, 最终得到是否符合要求
这里有一个优化点是：最终保留了整个中序遍历的数组，实际上是不需要的
每一步最后添加的元素就足以知道是或不是二叉搜索树了，请看方案2

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function isValidBST(root: TreeNode | null): boolean {
let stack = []; // 存储的是未拜访过的树中的节点的值
let inorder = -Infinity; // 存储上一个中序遍历到的树节点值
while (stack.length || root) {
// 不断将当前树节点的左子节点加入栈, 直到没有左节点
while (root) {
stack.push(root);
root = root.left;
}
root = stack.pop(); // 将当前子树最左边的节点从栈中取出
// 如果中序遍历得到的节点的值小于等于前一个 inorder，说明不是二叉搜索树
if (root.val <= inorder) {
return false;
}
inorder = root.val; // 将当前节点的值设为 inorder
root = root.right; // 将当前右子节点作为根节点，继续遍历
}
return true;
};
此方案也是官方示例，是 中序遍历，用到了递归, 是深度优先遍历
核心思想是对比的每一步都进行是否满足要求的校验, 节省了方案1的存储空间

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function isSameTree(p: TreeNode | null, q: TreeNode | null): boolean {
// 都为空时
if(!p && !q) return true;
// 不相同时
if (p?.val !== q?.val) return false;
// 递归判断
return isSameTree(p?.left, q?.left) && isSameTree(p?.right, q?.right);
};
解题思路
两棵树相同：根节点值相同，左子树相同，右子树相同
如此一来，我们把若干大问题，分解成若干个相似小问题
符合：分、解、合特性
选择分而治之
解题步骤
分：获取两个树的左子树和右子树
解：递归地判断两个树的左子树是否相同，右子树是否相同
合：将上述结果合并，若根节点值也相同，树就相同
时间复杂度：O(n)
n是所有节点数
空间复杂度：O(n)
递归，底部形成堆栈
n是树的节点数，最坏情况下，树的节点数是树的高度

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function isSameTree(p: TreeNode | null, q: TreeNode | null): boolean {
// 都为空时
if(!p && !q) return true;
// 不相同时
if (p?.val !== q?.val) return false;
// 声明两个队列
const queue1 = [p];
const queue2 = [q];
// 迭代对比
while (queue1.length && queue2.length) {
// 拿到队首
const pTop = queue1.shift();
const qTop = queue2.shift();
// 对比判断, 符合则提前终止
if (pTop.val !== qTop.val) return false;
// 拿到下一层
const pLeft = pTop?.left;
const pRight = pTop?.right;
const qLeft = qTop?.left;
const qRight = qTop?.right;
// 进入判断, 符合则提前终止
if ((pLeft && !qLeft) || (!pLeft && qLeft)) return false;
if ((pRight && !qRight) || (!pRight && qRight)) return false;
// 进入队列
if (pLeft) queue1.push(pLeft);
if (pRight) queue1.push(pRight);
if (qLeft) queue2.push(qLeft);
if (qRight) queue2.push(qRight);
}
// 最终结果对比
return !queue1.length && !queue2.length;
}
这里换一种广度优先遍历来对比两棵树是否相同
时间复杂度：O(n)
空间复杂度：O(n)

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function isSymmetric(root: TreeNode | null): boolean {
if(!root) return true;
const isMirror = (l: TreeNode | null, r: TreeNode | null) => {
if(!l && !r) return true; // 空树是镜像的
return l?.val === r?.val && isMirror(l?.left, r?.right) && isMirror(r?.left, l?.right)
};
return isMirror(root.left, root.right);
}
解题思路
转化为：左右子树是否镜像
分解为：树1的左子树和树2的左子树是否镜像；树1的右子树和树2的左子树是否镜像，成立，且根节点值相同，则镜像
符合：分、解、合的特性，考虑分而治之
解题步骤
分：获取两个树的左子树和右子树
解：递归地判断树1的左子树和树2的右子树是否镜像，树1的右子树和树2的左子树是否镜像
合：如果上述两个都成立，且根节点值也相同，两个树就是镜像
时间复杂度：O(n)
叶子节点数量
空间复杂度: O(n)
