// 遍历这一层的所有节点
for(let i = 0; i < size; i++) {
// 从队首取出元素
const node = Q.shift();
// 连接
if (i < size - 1) {
node.next = Q[0];
}
// 拓展下一层节点
if (node.left !== null) {
Q.push(node.left);
}
if (node.right !== null) {
Q.push(node.right);
}
}
}
// 返回根节点
return root;
};

