// 定义二叉树节点的接口
interface TreeNode {
val: number;
left: TreeNode | null;
right: TreeNode | null;
next: TreeNode | null;
}
function connect(root: TreeNode | null): TreeNode | null {
if (!root) return root;
// 从根节点开始
let leftmost = root;
while (leftmost.left) {
// 遍历这一层节点组织成的链表，为下一层的节点更新 next 指针
let head = leftmost;
while (head) {
// CONNECTION 1
head.left.next = head.right;
// CONNECTION 2
if (head.next) {
head.right.next = head.next.left;
}
// 指针向后移动
head = head.next;
}
// 去下一层的最左的节点
leftmost = leftmost.left;
}
return root;
}
