(n.neighbors || []).forEach(ne => {
if(!visited.has(ne)) {
dfs(ne);
}
nCopy.neighbors.push(visited.get(ne));
});
};
dfs(node);
return visited.get(node); // 将起始节点的拷贝作为克隆图的引用返回
}
