function compareVersion(version1: string, version2: string): number {
let i = 0, j = 0;
const n = version1.length, m = version2.length;
while (i < n || j < m) {
let x = 0;
// 解析 version1 的当前修订号
for (; i < n && version1[i] !== '.'; ++i) {
x = x * 10 + parseInt(version1[i], 10);
}
++i; // 跳过点号
let y = 0;
// 解析 version2 的当前修订号
for (; j < m && version2[j] !== '.'; ++j) {
y = y * 10 + parseInt(version2[j], 10);
}
++j; // 跳过点号
if (x !== y) {
return x > y ? 1 : -1;
}
}
return 0;
}
