function largestNumber(nums: number[]): string {
// 自定义排序规则
nums.sort((x: number, y: number): number => {
let sx: number = 10, sy: number = 10;
// 计算 sx 和 sy 使得 sx * y + x 和 sy * x + y 可以直接比较
while (sx <= x) {
sx *= 10;
}
while (sy <= y) {
sy *= 10;
}
// 比较拼接后的结果
return Number(`${sx * y + x}`) - Number(`${sy * x + y}`);
});
// 如果最大的数是 0，则直接返回 '0'
if (nums[0] === 0) {
return '0';
}
// 连接所有数字并返回
return nums.join('');
}

function largestNumber(nums: number[]): string {
// 将数字数组转换为字符串数组
const strs: string[] = nums.map(num => num.toString());
// 自定义排序规则
strs.sort((x, y) => (y + x).localeCompare(x + y));
// 如果最大的数是 "0"，则直接返回 "0"
if (strs[0] === "0") return "0";
// 连接所有字符串并返回
return strs.join('');
}

function quickSort(strs: string[], l: number, r: number): void {
if (l >= r) return;
let i = l, j = r;
let tmp = strs[i];
while (i < j) {
while ((strs[j] + strs[l]).localeCompare(strs[l] + strs[j]) >= 0 && i < j) j--;
while ((strs[i] + strs[l]).localeCompare(strs[l] + strs[i]) <= 0 && i < j) i++;
[strs[i], strs[j]] = [strs[j], strs[i]];
}
[strs[i], strs[l]] = [strs[l], strs[i]];
quickSort(strs, l, i - 1);
quickSort(strs, i + 1, r);
}
function largestNumber(nums: number[]): string {
const strs: string[] = nums.map(num => num.toString());
quickSort(strs, 0, strs.length - 1);
let res = '';
if (strs[strs.length - 1] === '0') {
return '0';
}
for (let i = strs.length - 1; i >= 0; i--) {
res += strs[i];
}
return res;
}
