/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function rightSideView(root: TreeNode | null): number[] {
const rightmostValueAtDepth: { [key: number]: number } = {};
let maxDepth = -1;
const nodeStack: TreeNode[] = [];
const depthStack: number[] = [];
nodeStack.push(root);
depthStack.push(0);
while (nodeStack.length > 0) {
const node = nodeStack.pop()!;
const depth = depthStack.pop()!;
if (node === null) continue;
// 维护二叉树的最大深度
maxDepth = Math.max(maxDepth, depth);
// 如果不存在对应深度的节点我们才插入
if (!(depth in rightmostValueAtDepth)) {
rightmostValueAtDepth[depth] = node.val;
}
nodeStack.push(node.left);
nodeStack.push(node.right);
depthStack.push(depth + 1);
depthStack.push(depth + 1);
}
const rightView: number[] = [];
for (let depth = 0; depth <= maxDepth; depth++) {
rightView.push(rightmostValueAtDepth[depth]);
}
return rightView;
}

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function rightSideView(root: TreeNode | null): number[] {
const rightmostValueAtDepth: { [depth: number]: number } = {};
let maxDepth = -1;
const nodeQueue: TreeNode[] = [];
const depthQueue: number[] = [];
if (root !== null) {
nodeQueue.push(root);
depthQueue.push(0);
}
while (nodeQueue.length > 0) {
const node = nodeQueue.shift()!;
const depth = depthQueue.shift()!;
if (node !== null) {
// 维护二叉树的最大深度
maxDepth = Math.max(maxDepth, depth);
// 由于每一层最后一个访问到的节点才是我们要的答案，因此不断更新对应深度的信息即可
rightmostValueAtDepth[depth] = node.val;
if (node.left !== null) {
nodeQueue.push(node.left);
depthQueue.push(depth + 1);
}
if (node.right !== null) {
nodeQueue.push(node.right);
depthQueue.push(depth + 1);
}
}
}
const rightView: number[] = [];
for (let depth = 0; depth <= maxDepth; depth++) {
rightView.push(rightmostValueAtDepth[depth]);
}
return rightView;
}
