function minSubArrayLen(target: number, nums: number[]): number {
const n = nums.length;
if (n === 0) return 0;
let ans = Number.MAX_SAFE_INTEGER;
for (let i = 0; i < n; i++) {
let sum = 0;
for (let j = i; j < n; j++) {
sum += nums[j];
if (sum >= target) {
ans = Math.min(ans, j - i + 1);
break;
}
}
}
return ans === Number.MAX_SAFE_INTEGER ? 0 : ans;
}

function minSubArrayLen(target: number, nums: number[]): number {
const n = nums.length;
if (n === 0) return 0;
let ans = Number.MAX_SAFE_INTEGER;
const sums: number[] = new Array(n + 1).fill(0);
// 计算前缀和
for (let i = 1; i <= n; i++) {
sums[i] = sums[i - 1] + nums[i - 1];
}
// 辅助函数：实现二分查找
function binarySearch(arr: number[], target: number): number {
let low = 0;
let high = arr.length - 1;
while (low <= high) {
const mid = Math.floor((low + high) / 2);
if (arr[mid] < target) {
low = mid + 1;
} else {
high = mid - 1;
}
}
return low;
}
// 查找满足条件的子数组长度
for (let i = 1; i <= n; i++) {
const t = target + sums[i - 1];
const bound = binarySearch(sums, t);
if (bound <= n && sums[bound] >= t) {
ans = Math.min(ans, bound - (i - 1));
}
}
return ans === Number.MAX_SAFE_INTEGER ? 0 : ans;
}

function minSubArrayLen(target: number, nums: number[]): number {
const n = nums.length;
if (n === 0) return 0;
let ans = Number.MAX_SAFE_INTEGER;
let start = 0;
let end = 0;
let sum = 0;
while (end < n) {
sum += nums[end];
while (sum >= target) {
ans = Math.min(ans, end - start + 1);
sum -= nums[start];
start++;
}
end++;
}
return ans === Number.MAX_SAFE_INTEGER ? 0 : ans;
}

function rob(nums: number[]): number {
const n = nums.length;
if (n === 0) return 0;
if (n === 1) return nums[0];
// dp1 不抢最后一个房子, dp2 不抢第一个房子
const dp1: number[] = new Array(n).fill(0);
const dp2: number[] = new Array(n).fill(0);
dp1[0] = nums[0];
dp1[1] = Math.max(nums[0], nums[1]);
dp2[1] = nums[1];
for (let i = 2; i < n; ++i) {
dp1[i] = Math.max(dp1[i - 1], dp1[i - 2] + nums[i]);
dp2[i] = Math.max(dp2[i - 1], dp2[i - 2] + nums[i]);
}
// 对于 dp2，我们从第二个元素开始计算，因此需要单独处理
for (let i = 2; i < n - 1; ++i) {
dp2[i] = Math.max(dp2[i - 1], dp2[i - 2] + nums[i]);
}
return Math.max(dp1[n - 2], dp2[n - 1]);
}

function rob(nums: number[]): number {
const len = nums.length
if(len === 0) return 0
if(len === 1) return nums[0]
const ret1 = robRange(nums,0,len-2)
const ret2 = robRange(nums,1,len-1)
return Math.max(ret1,ret2)
};
function robRange(nums,start,end) {
if(end === start) return nums[start]
const dp = new Array(nums.length).fill(0)
dp[start] = nums[start]
dp[start+1] = Math.max(nums[start],nums[start+1])
for(let i=start+2; i<=end; i++) {
dp[i] = Math.max(dp[i-2]+nums[i],dp[i-1])
}
return dp[end]
}

function rob(nums: number[]): number {
const length = nums.length;
if (length === 1) {
return nums[0];
} else if (length === 2) {
return Math.max(nums[0], nums[1]);
}
return Math.max(robRange(nums, 0, length - 2), robRange(nums, 1, length - 1));
}
const robRange = (nums, start, end) => {
let first = nums[start], second = Math.max(nums[start], nums[start + 1]);
for (let i = start + 2; i <= end; i++) {
const temp = second;
second = Math.max(first + nums[i], second);
first = temp;
}
return second;
}

