// 计算二叉树中节点数的函数
function countNodes(root: TreeNode | null): number {
if (root === null) return 0;
const leftHeight = countLevel(root.left);
const rightHeight = countLevel(root.right);
// 如果左子树和右子树的高度相同，说明左子树是满二叉树
// 因此，可以直接通过左子树的高度计算出左子树的节点数（2^leftHeight - 1），并加上根节点和右子树的节点数
if (leftHeight === rightHeight) {
return countNodes(root.right) + (1 << leftHeight);
}
// 否则，右子树是满二叉树（或者更准确地说，是高度为rightHeight的完全二叉树的一部分）
// 因此，可以直接通过右子树的高度计算出右子树的节点数的上限（注意这里不是严格的满二叉树节点数，但因为左子树不是满二叉树，所以这样计算是安全的）
// 并加上根节点和左子树的节点数
return countNodes(root.left) + (1 << rightHeight);
}
// 计算左子树或右子树的高度（或深度）
function countLevel(root: TreeNode | null): number {
let level = 0;
while (root !== null) {
level++;
root = root.left;
}
return level;
}
