/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function kthSmallest(root: TreeNode | null, k: number): number {
const stack = [];
while (root != null || stack.length) {
while (root != null) {
stack.push(root);
root = root.left;
}
root = stack.pop();
--k;
if (k === 0) break;
root = root.right;
}
return root.val;
};

function kthSmallest(root: TreeNode | null, k: number): number {
const bst = new MyBst(root);
return bst.kthSmallest(k);
}
class MyBst {
private root: TreeNode | null; // 声明root属性
private nodeNum: Map<TreeNode | null, number>; // 声明nodeNum属性
constructor(root: TreeNode | null) {
this.root = root; // 初始化root属性
this.nodeNum = new Map(); // 初始化nodeNum属性
this.countNodeNum(root); // 调用方法填充nodeNum Map
}
// 返回二叉搜索树中第k小的元素
kthSmallest(k: number): number {
let node = this.root;
while (node != null) {
const left = this.getNodeNum(node.left);
if (left < k - 1) {
node = node.right;
k -= left + 1;
} else if (left === k - 1) {
break;
} else {
node = node.left;
}
}
return node!.val; // 使用非空断言操作符，因为我们知道在循环结束时node不会是null（如果k是有效的）
}
// 统计以node为根结点的子树的结点数
private countNodeNum(node: TreeNode | null): number {
if (node == null) {
return 0;
}
this.nodeNum.set(node, 1 + this.countNodeNum(node.left) + this.countNodeNum(node.right));
return this.nodeNum.get(node)!; // 使用非空断言操作符，因为set之后一定会存在
}
// 获取以node为根结点的子树的结点数
private getNodeNum(node: TreeNode | null): number {
return this.nodeNum.get(node) || 0;
}
}
