* this.right = (right===undefined ? null : right)
* }
* }
*/
function lowestCommonAncestor(root: TreeNode | null, p: TreeNode | null, q: TreeNode | null): TreeNode | null {
const parent: Record<number, TreeNode> = {};
const visited: Record<number, boolean> = {};
const dfs = (r: TreeNode | null) => {
if (!r) return;
if (r.left) {
parent[r.left.val] = r;
dfs(r.left);
}
if (r.right) {
parent[r.right.val] = r;
dfs(r.right);
}
};
dfs(root);
let current: TreeNode | null = p;
while (current) {
visited[current.val] = true;
current = parent[current.val] as TreeNode | null;
}
current = q;
while (current) {
if (visited[current.val]) {
return current;
}
current = parent[current.val] as TreeNode | null;
}
return null;
}
