class Heap<T> {
private heap: T[] = [];
private compareFn: (a: T, b: T) => boolean;
constructor(compareFn: (a: T, b: T) => boolean) {
this.compareFn = compareFn;
}
swap(i: number, j: number): void {
[this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];
}
getParentIndex(i: number): number {
return Math.floor((i - 1) / 2);
}
getLeftChildIndex(pi: number): number {
return 2 * pi + 1;
}
getRightChildIndex(pi: number): number {
return 2 * pi + 2;
}
peek(): T | undefined {
return this.heap[0];
}
size(): number {
return this.heap.length;
}
insert(value: T): void {
this.heap.push(value);
this.shiftUp(this.size() - 1);
}
pop(): T | undefined {
const { heap } = this;
if (this.size() === 1) return heap.pop();
const first = heap[0];
heap[0] = heap.pop()!;
this.shiftDown(0);
return first;
}
shiftUp(i: number): void {
if (i <= 0) return;
const { heap } = this;
const pi = this.getParentIndex(i);
if (this.compareFn(heap[pi]!, heap[i]!)) {
this.swap(pi, i);
this.shiftUp(pi);
}
}
shiftDown(pi: number): void {
const { heap } = this;
const size = this.size();
const li = this.getLeftChildIndex(pi);
const ri = this.getRightChildIndex(pi);
if (li < size && this.compareFn(heap[pi]!, heap[li]!)) {
this.swap(pi, li);
this.shiftDown(li);
}
if (ri < size && this.compareFn(heap[pi]!, heap[ri]!)) {
this.swap(pi, ri);
this.shiftDown(ri);
}
}
}
class MinHeap extends Heap<number> {
constructor() {
super((a, b) => a > b);
}
}
class MaxHeap extends Heap<number> {
constructor() {
super((a, b) => a < b);
}
}
