this.compareFn = compareFn;
}
protected swap(i: number, j: number): void {
[this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];
}
protected getParentIndex(i: number): number {
return (i - 1) >> 1;
}
protected getLeftIndex(pi: number): number {
return (pi << 1) + 1;
}
protected getRightIndex(pi: number): number {
return (pi << 1) + 2;
}
public peak(): number | undefined {
return this.heap[0];
}
public size(): number {
return this.heap.length;
}
public isEmpty(): boolean {
return this.size() === 0;
}
public insert(value: number): void {
this.heap.push(value);
this.shiftUp(this.size() - 1);
}
public pop(): number | undefined {
if (this.size() === 0) return undefined;
if (this.size() === 1) return this.heap.pop();
const first = this.heap[0];
this.heap[0] = this.heap.pop()!;
this.shiftDown(0);
return first;
}
protected shiftUp(i: number): void {
while (i > 0 && this.compareFn(this.heap[this.getParentIndex(i)], this.heap[i])) {
this.swap(this.getParentIndex(i), i);
i = this.getParentIndex(i);
}
}
protected shiftDown(pi: number): void {
let largest = pi;
const left = this.getLeftIndex(pi);
const right = this.getRightIndex(pi);
if (left < this.size() && this.compareFn(this.heap[largest], this.heap[left])) {
largest = left;
}
if (right < this.size() && this.compareFn(this.heap[largest], this.heap[right])) {
largest = right;
}
if (largest !== pi) {
this.swap(pi, largest);
this.shiftDown(largest);
}
}
}
