class MedianFinder {
private nums: Map<number, number> = new Map();
private orderedKeys: number[] = [];
private n: number = 0;
private left: [number, number] = [0, 0];
private right: [number, number] = [0, 0];
constructor() {}
public addNum(num: number): void {
// Update the frequency of the number in the map
const count = this.nums.get(num) || 0;
this.nums.set(num, count + 1);
// Maintain the ordered keys list
if (!this.orderedKeys.includes(num)) {
const index = this.bisectLeft(this.orderedKeys, num);
this.orderedKeys.splice(index, 0, num);
}
if (this.n === 0) {
this.left = [num, 1];
this.right = [num, 1];
} else if ((this.n & 1) !== 0) {
if (num < this.left[0]) {
this.decrease('left');
} else {
this.increase('right');
}
} else {
if (num > this.left[0] && num < this.right[0]) {
this.increase('left');
this.decrease('right');
} else if (num >= this.right[0]) {
this.increase('left');
} else {
this.decrease('right');
this.left = [...this.right];
}
}
this.n++;
}
public findMedian(): number {
return (this.left[0] + this.right[0]) / 2;
}
private increase(iterator: 'left' | 'right'): void {
const it = iterator === 'left' ? this.left : this.right;
it[1]++;
if (it[1] > (this.nums.get(it[0]) || 0)) {
const nextKeyIndex = this.bisectLeft(this.orderedKeys, it[0] + 1);
it[0] = nextKeyIndex < this.orderedKeys.length ? this.orderedKeys[nextKeyIndex] : this.orderedKeys[this.orderedKeys.length - 1];
it[1] = 1;
}
}
private decrease(iterator: 'left' | 'right'): void {
const it = iterator === 'left' ? this.left : this.right;
it[1]--;
if (it[1] <= 0) {
const prevKeyIndex = this.bisectRight(this.orderedKeys, it[0] - 1) - 1;
it[0] = prevKeyIndex >= 0 ? this.orderedKeys[prevKeyIndex] : this.orderedKeys[0];
it[1] = this.nums.get(it[0]) || 0;
}
}
private bisectLeft(arr: number[], x: number): number {
let lo = 0, hi = arr.length;
while (lo < hi) {
const mid = Math.floor((lo + hi) / 2);
if (arr[mid] < x) lo = mid + 1;
else hi = mid;
}
return lo;
}
private bisectRight(arr: number[], x: number): number {
let lo = 0, hi = arr.length;
while (lo < hi) {
const mid = Math.floor((lo + hi) / 2);
if (x < arr[mid]) hi = mid;
else lo = mid + 1;
}
return lo;
}
}
