function lengthOfLIS(nums: number[]): number {
const n = nums.length;
if (!n) return 0;
// 初始化dp数组，每个元素设为1，因为最小的递增子序列长度为1（即自身）
const dp: number[] = new Array(n).fill(1);
// 双重循环，在每个节点都要重新遍历一次进行判断
for (let i = 0; i < n; ++i) {
for (let j = 0; j < i; ++j) {
if (nums[j] < nums[i]) {
dp[i] = Math.max(dp[i], dp[j] + 1);
}
}
}
// 找到dp数组中的最大值
return Math.max(...dp);
}

function lengthOfLIS(nums: number[]): number {
const n = nums.length;
if (!n) return 0;
const dp: number[] = new Array(n).fill(0);
let count: number = 0;
for (const num of nums) {
let i: number = 0;
let j: number = count;
while (i < j) {
const m: number = Math.floor((i + j) >> 1);
(dp[m] < num) ? (i = m + 1) : (j = m);
}
dp[i] = num;
(j === count) && (++ count);
}
return count;
}
