function nthSuperUglyNumber (n: number, primes: number[]) {
const dp = new Array(n + 1).fill(0);
const m = primes.length;
const pointers = new Array(m).fill(0);
const nums = new Array(m).fill(1);
for (let i = 1; i <= n; i++) {
let minNum = Number.MAX_SAFE_INTEGER;
for (let j = 0; j < m; j++) {
minNum = Math.min(minNum, nums[j]);
}
dp[i] = minNum;
for (let j = 0; j < m; j++) {
if (nums[j] == minNum) {
pointers[j]++;
nums[j] = dp[pointers[j]] * primes[j];
}
}
}
return dp[n];
};
这是官方做法, 动态规划解决了递归的问题，由递归变成了递推
时间复杂度 O(nm) ≈ O(n^2)

function coinChange(coins: number[], amount: number): number {
if (amount < 1) return 0;
const count = new Array(amount).fill(0);
return helper(coins, amount, count);
}
function helper(coins: number[], rem: number, count: number[]): number {
if (rem < 0) return -1;
if (rem === 0) return 0;
if (count[rem - 1] !== 0) return count[rem - 1];
let min = Number.MAX_SAFE_INTEGER;
for (const coin of coins) {
const res = helper(coins, rem - coin, count);
if (res >= 0 && res < min) {
min = 1 + res;
}
}
count[rem - 1] = (min === Number.MAX_SAFE_INTEGER) ? -1 : min;
return count[rem - 1];
}

function coinChange(coins: number[], amount: number): number {
const max = amount + 1;
const dp: number[] = new Array(amount + 1).fill(max);
dp[0] = 0;
for (let i = 1; i <= amount; i++) {
for (const coin of coins) {
if (coin <= i) {
dp[i] = Math.min(dp[i], dp[i - coin] + 1);
}
}
}
return dp[amount] > amount ? -1 : dp[amount];
}

function coinChange(coins: number[], amount: number): number {
if (!amount) return 0;
const dp: number[] = Array(amount + 1).fill(Infinity);
dp[0] = 0;
for (const coin of coins) {
for (let j = coin; j <= amount; j++) {
dp[j] = Math.min(dp[j], dp[j - coin] + 1);
}
}
return dp[amount] === Infinity ? -1 : dp[amount];
}
