function flatArray(arr: any[]): any[] {
const stack = [...arr];
const ret: any[] = [];
while (stack.length) {
let next = stack.pop();
if (Array.isArray(next)) {
stack.push(...next);
} else {
ret.unshift(next); // 使用 unshift 来保持原始顺序
}
}
return ret;
