function canConstruct(ransomNote: string, magazine: string): boolean {
if (ransomNote.length > magazine.length) return false;
// 创建一个长度为26的数组来存储每个字母的出现次数
const cnt: number[] = new Array(26).fill(0);
// 遍历 magazine 字符串，统计每个字母的出现次数
for (const c of magazine) {
cnt[c.charCodeAt(0) - 'a'.charCodeAt(0)]++;
}
// 遍历 ransomNote 字符串，检查是否可以构造出 ransomNote
for (const c of ransomNote) {
const index = c.charCodeAt(0) - 'a'.charCodeAt(0);
cnt[index]--;
if (cnt[index] < 0) {
return false;
}
}
return true;
}

function canConstruct(ransomNote: string, magazine: string): boolean {
// 创建一个长度为26的数组来存储每个字母的出现次数
const arr: number[] = new Array(26).fill(0);
// 计算 'a' 的 char code，用于后续计算字符在数组中的索引
const base: number = 'a'.charCodeAt(0);
// 遍历 magazine 字符串，统计每个字母的出现次数
for (const m of magazine) {
arr[m.charCodeAt(0) - base]++;
}
// 遍历 ransomNote 字符串，减少相应字母的计数
for (const r of ransomNote) {
arr[r.charCodeAt(0) - base]--;
}
// 检查所有字母的计数是否都大于等于0
return arr.every(v => v >= 0);
}
