function isSubsequence(s: string, t: string): boolean {
const n = s.length;
const m = t.length;
const f: number[][] = Array.from({ length: m + 1 }, () => Array(26).fill(m));
// Fill the last row of f with m
for (let i = 0; i < 26; i++) {
f[m][i] = m;
}
// Fill the DP table from bottom to top
for (let i = m - 1; i >= 0; i--) {
for (let j = 0; j < 26; j++) {
if (t.charCodeAt(i) === j + 'a'.charCodeAt(0)) {
f[i][j] = i;
} else {
f[i][j] = f[i + 1][j];
}
}
}
let add = 0;
for (let i = 0; i < n; i++) {
const charIndex = s.charCodeAt(i) - 'a'.charCodeAt(0);
if (f[add][charIndex] === m) {
return false;
}
add = f[add][charIndex] + 1;
}
return true;
}

