* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
// 计算所有左叶子节点的和的函数
function sumOfLeftLeaves(root: TreeNode | null): number {
let leftSum = 0
function travese(node){
if(!node) return
// left是单独的节点
let left = node.left
if(left && !left.left && !left.right){
leftSum += left.val
}
// left有嵌套，走递归
travese(node.left)
travese(node.right)
}
travese(root)
return leftSum
};

