function addStrings(num1: string, num2: string): string {
let i = num1.length - 1;
let j = num2.length - 1;
let carry = 0;
const ans: number[] = [];
while (i >= 0 || j >= 0 || carry !== 0) {
const x = i >= 0 ? parseInt(num1.charAt(i), 10) : 0;
const y = j >= 0 ? parseInt(num2.charAt(j), 10) : 0;
const sum = x + y + carry;
ans.push(sum % 10);
carry = Math.floor(sum / 10);
i -= 1;
j -= 1;
}
return ans.reverse().join('');
}

function addStrings(num1: string, num2: string): string {
let i = num1.length - 1;
let j = num2.length - 1;
let carry = 0;
const res: string[] = [];
while (i >= 0 || j >= 0 || carry > 0) {
const n1 = i >= 0 ? parseInt(num1.charAt(i), 10) : 0;
const n2 = j >= 0 ? parseInt(num2.charAt(j), 10) : 0;
const tmp = n1 + n2 + carry;
carry = Math.floor(tmp / 10);
res.push((tmp % 10).toString());
i--;
j--;
}
return res.reverse().join('');
}
