/**
* Definition for _Node.
* class _Node {
* val: number
* children: _Node[]
*
* constructor(v: number) {
* this.val = v;
* this.children = [];
* }
* }
*/
function levelOrder(root: _Node | null): number[][] {
if (!root) return [];
const ans = [];
const queue = [root];
while (queue.length) {
const cnt = queue.length;
const level = [];
for (let i = 0; i < cnt; ++i) {
const cur = queue.shift();
level.push(cur.val);
for (const child of cur.children) {
queue.push(child);
}
}
ans.push(level);
}
return ans;
};

/**
* Definition for _Node.
* class _Node {
* val: number
* children: _Node[]
*
* constructor(v: number) {
* this.val = v;
* this.children = [];
* }
* }
*/
function levelOrder(root: _Node | null): number[][] {
if (root === null) return [];
let ans = [];
let cur = [root];
while (cur.length) {
let nxt = [];
let vals = [];
for (const node of cur) {
vals.push(node.val);
nxt.push(...node.children);
}
ans.push(vals);
cur = nxt;
}
return ans;
};
