class MaxHeap {
map: Map<string, number> = new Map()
heap: number[] = []
init(str:string) {
// 构建map字典
const { map } = this;
str.split('').forEach(item => {
map.set(item, map.has(item) ? map.get(item) + 1 : 1);
});
this.heap = Array.from(map.values());
}
sort () {
const iArr = this.heap;
const n = iArr.length;
if (n <= 1) return iArr;
for (let i = Math.floor(n / 2); i >= 0; i--) {
MaxHeap.maxHeapify(iArr, i, n);
}
for (let j = 0; j < n; j++) {
MaxHeap.swap(iArr, 0, n - 1 - j);
MaxHeap.maxHeapify(iArr, 0, n - 1 - j - 1);
}
return iArr;
}
// 排序并转成字符串
sortToString () {
const arr = this.sort(); // 这里对值进行排序
const str = [];
while (arr.length) {
const top = arr.pop();
for (const [k, v] of this.map) {
// 值和值匹配
if (v === top) {
str.push(k.repeat(v));
this.map.delete(k); // 使用过的key防止重复匹配 这里记得删除
break
}
}
}
return str.join('');
}
// 交换两个元素
static swap (arr, i, j) {
if (i === j) return;
[arr[i], arr[j]] = [arr[j], arr[i]];
}
// 构建最大堆的过程
static maxHeapify (Arr, i, size) {
// 左节点（索引）
const l = (i << 1) + 1;
// 右节点
const r = (i << 1) + 2;
let largest = i;
// 父节点i和左节点l做比较取最大
if (l <= size && Arr[l] > Arr[largest]) largest = l;
// 右节点和最大值比较
if (r <= size && Arr[r] > Arr[largest]) largest = r;
if (largest !== i) {
MaxHeap.swap(Arr, i, largest);
MaxHeap.maxHeapify(Arr, largest, size);
}
}
}
function frequencySort(s: string): string {
const mh = new MaxHeap();
mh.init(s);
return mh.sortToString();
}
