function change(amount: number, coins: number[]): number {
const n = coins.length;
const memo: number[][] = Array.from({ length: n }, () => Array(amount + 1).fill(-1));
function dfs(i: number, c: number): number {
if (i < 0) {
return c === 0 ? 1 : 0;
}
if (memo[i][c] !== -1) {
return memo[i][c];
}
if (c < coins[i]) {
return memo[i][c] = dfs(i - 1, c);
}
return memo[i][c] = dfs(i - 1, c) + dfs(i, c - coins[i]);
}
return dfs(n - 1, amount);
}

function change(amount: number, coins: number[]): number {
const dp = new Array(amount + 1).fill(0);
const valid = new Array(amount + 1).fill(false);
dp[0] = 1;
valid[0] = true;
for (const coin of coins) {
for (let i = coin; i <= amount; i++) {
valid[i] |= valid[i - coin];
}
}
if (!valid[amount]) return 0;
for (const coin of coins) {
for (let i = coin; i <= amount; i++) {
dp[i] += dp[i - coin];
}
}
return dp[amount];
}

function change(amount: number, coins: number[]): number {
const n = coins.length;
const f: number[][] = Array.from({ length: n + 1 }, () => Array(amount + 1).fill(0));
f[0][0] = 1;
for (let i = 0; i < n; i++) {
for (let c = 0; c <= amount; c++) {
if (c < coins[i]) {
f[i + 1][c] = f[i][c];
} else {
f[i + 1][c] = f[i][c] + f[i + 1][c - coins[i]];
}
}
}
return f[n][amount];
}

