function checkInclusion(s1: string, s2: string): boolean {
const n: number = s1.length;
const m: number = s2.length;
// 如果 s1 的长度大于 s2，则不可能有排列包含在 s2 中
if (n > m) {
return false;
}
// 创建两个数组来存储 s1 和当前窗口中每个字符的频率
const cnt1: number[] = new Array(26).fill(0);
const cnt2: number[] = new Array(26).fill(0);
// 统计 s1 和 s2 前 n 个字符的频率
for (let i = 0; i < n; ++i) {
cnt1[s1.charCodeAt(i) - 'a'.charCodeAt(0)]++;
cnt2[s2.charCodeAt(i) - 'a'.charCodeAt(0)]++;
}
// 检查初始窗口是否匹配
if (cnt1.toString() === cnt2.toString()) {
return true;
}
// 滑动窗口遍历 s2 的其余部分
for (let i = n; i < m; ++i) {
// 更新当前窗口的频率计数
cnt2[s2.charCodeAt(i) - 'a'.charCodeAt(0)]++;
cnt2[s2.charCodeAt(i - n) - 'a'.charCodeAt(0)]--;
// 检查当前窗口是否匹配
if (cnt1.toString() === cnt2.toString()) {
return true;
}
}
return false;
}

function checkInclusion(s1: string, s2: string): boolean {
const n: number = s1.length;
const m: number = s2.length;
// 如果 s1 的长度大于 s2，则不可能有排列包含在 s2 中
if (n > m) {
return false;
}
// 创建一个数组来存储字符频率差异
const cnt: number[] = new Array(26).fill(0);
// 统计 s1 和 s2 前 n 个字符的频率差异
for (let i = 0; i < n; ++i) {
--cnt[s1.charCodeAt(i) - 'a'.charCodeAt(0)];
++cnt[s2.charCodeAt(i) - 'a'.charCodeAt(0)];
}
let diff: number = 0;
for (const c of cnt) {
if (c !== 0) {
++diff;
}
}
// 检查初始窗口是否匹配
if (diff === 0) {
return true;
}
// 滑动窗口遍历 s2 的其余部分
for (let i = n; i < m; ++i) {
const x: number = s2.charCodeAt(i) - 'a'.charCodeAt(0);
const y: number = s2.charCodeAt(i - n) - 'a'.charCodeAt(0);
if (x === y) {
continue;
}
// 更新字符频率差异并调整 diff
if (cnt[x] === 0) {
++diff;
}
++cnt[x];
if (cnt[x] === 0) {
--diff;
}
if (cnt[y] === 0) {
++diff;
}
--cnt[y];
if (cnt[y] === 0) {
--diff;
}
// 检查当前窗口是否匹配
if (diff === 0) {
return true;
}
}
return false;
}

function checkInclusion(s1: string, s2: string): boolean {
const n: number = s1.length;
const m: number = s2.length;
// 如果 s1 的长度大于 s2，则不可能有排列包含在 s2 中
if (n > m) {
return false;
}
// 创建一个数组来存储字符频率差异
const cnt: number[] = new Array(26).fill(0);
// 统计 s1 的每个字符的频率差异
for (let i = 0; i < n; ++i) {
--cnt[s1.charCodeAt(i) - 'a'.charCodeAt(0)];
}
let left: number = 0;
// 使用滑动窗口遍历 s2
for (let right = 0; right < m; ++right) {
const x: number = s2.charCodeAt(right) - 'a'.charCodeAt(0);
++cnt[x];
// 如果当前字符频率超出，调整左边界
while (cnt[x] > 0) {
--cnt[s2.charCodeAt(left) - 'a'.charCodeAt(0)];
++left;
}
// 检查当前窗口大小是否与 s1 长度相等
if (right - left + 1 === n) {
return true;
}
}
return false;
}
