// 判断是否能在花坛中种植指定数量的花
function canPlaceFlowers(flowerbed: number[], n: number): boolean {
// 左边界，初始为虚拟节点
let l = -1;
// 右边界
let r = 0;
// 遍历花坛数组
while (r <= flowerbed.length) {
// 获取右边界的值，若超出范围则为虚拟节点值
const rv = r === flowerbed.length ? 0 : flowerbed[r];
// 右边界右移
r++;
// 如果右边界是已种植的花，则更新左边界为右边界
if (rv === 1) {
l = r;
}
// 如果两边界相隔3个位置，则可以在中间位置种植一朵花
if (r - l === 3) {
// 减去需要种植的花的数量
n--;
// 更新左边界为下一个位置
l += 2;
}
}
// 若需要种植的花的数量小于等于0，则表示可以完成种植
return n <= 0;
}
初始化边界
将左边界 l 初始化为虚拟节点（-1），表示初始时还没有遇到任何已种植的花。
将右边界 r 初始化为花坛数组的起始位置（0）。
遍历花坛数组
从左到右遍历花坛数组，确保在数组范围内。
更新右边界和检查已种植的花
获取右边界 r 的值 rv，如果超出花坛数组范围，则将其设为虚拟节点值 0。
右边界 r 向右移动。
更新左边界
如果右边界的值 rv 是已种植的花（值为 1），则将左边界 l 更新为当前右边界 r。
判断是否可以在中间位置种植花
如果右边界与左边界相隔 3 个位置（r - l === 3），表示在这两朵已种植的花之间有足够的空地可以种植新花。
将需要种植的花的数量 n 减一。
将左边界 l 更新为下一个位置（l += 2），以继续检查下一个区间。
判断是否完成种植
当所有花坛遍历完毕后，检查剩余需要种植的花的数量 n 是否小于等于 0。
如果小于等于 0，则表示可以完成种植，返回 true；否则，表示不能完成种植，返回 false。
通过维护左右边界和逐步判断每两朵已种植的花之间的空地情况
