* this.right = (right===undefined ? null : right)
* }
* }
*/
function mergeTrees(t1: TreeNode | null, t2: TreeNode | null): TreeNode {
if (t1 === null) {
return t2 !== null ? { val: t2.val, left: t2.left, right: t2.right } : null;
}
if (t2 === null) {
return { val: t1.val, left: t1.left, right: t1.right };
}
const merged: TreeNode = {
val: t1.val + t2.val,
left: mergeTrees(t1.left, t2.left),
right: mergeTrees(t1.right, t2.right)
};
return merged;
}

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function mergeTrees(t1: TreeNode | null, t2: TreeNode | null): TreeNode | null {
if (!t1) return t2;
if (!t2) return t1;
const merged = new TreeNode(t1.val + t2.val);
const queue: TreeNode[] = [merged];
const queue1: TreeNode[] = [t1];
const queue2: TreeNode[] = [t2];
while (queue1.length && queue2.length) {
const node = queue.shift()!;
const node1 = queue1.shift()!;
const node2 = queue2.shift()!;
let left1 = node1.left, right1 = node1.right;
let left2 = node2.left, right2 = node2.right;
if (left1 || left2) {
if (left1 && left2) {
const left = new TreeNode(left1.val + left2.val);
node.left = left;
queue.push(left);
queue1.push(left1);
queue2.push(left2);
} else if (left1) {
node.left = left1;
} else { // left2 !== null
node.left = left2;
}
}
if (right1 || right2) {
if (right1 && right2) {
const right = new TreeNode(right1.val + right2.val);
node.right = right;
queue.push(right);
queue1.push(right1);
queue2.push(right2);
} else if (right1) {
node.right = right1;
} else { // right2 !== null
node.right = right2;
}
}
}
return merged;
}
