*/
function averageOfLevels(root: TreeNode | null): number[] {
function dfs(node: TreeNode | null, level: number, totals: number[], counts: number[]): void {
if (!node) return;
if (level < totals.length) {
totals[level] += node.val;
counts[level] += 1;
} else {
totals.push(node.val);
counts.push(1);
}
if (node.left) dfs(node.left, level + 1, totals, counts);
if (node.right) dfs(node.right, level + 1, totals, counts);
}
const totals: number[] = [];
const counts: number[] = [];
if (root) dfs(root, 0, totals, counts);
return totals.map((total, index) => total / counts[index]);
}

/**
* Definition for a binary tree node.
* class TreeNode {
* val: number
* left: TreeNode | null
* right: TreeNode | null
* constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.left = (left===undefined ? null : left)
* this.right = (right===undefined ? null : right)
* }
* }
*/
function averageOfLevels(root: TreeNode | null): number[] {
const averages: number[] = [];
const queue: TreeNode[] = [root];
while (queue.length > 0) {
let total = 0;
const size = queue.length;
for (let i = 0; i < size; i++) {
const node = queue.shift()!;
total += node.val;
if (node.left) {
queue.push(node.left);
}
if (node.right) {
queue.push(node.right);
}
}
averages.push(total / size);
}
return averages;
}
