function findLengthOfLCIS(nums: number[]): number {
const n = nums.length;
if (n <= 1) return n;
let start = 0;
let ans = 0;
for (let i = 0; i < n; i++) {
if (i > 0 && nums[i] <= nums[i - 1]) {
start = i;
}
ans = Math.max(ans, i - start + 1);
}
return ans;
};

function findLengthOfLCIS(nums: number[]): number {
const n = nums.length;
if (n <= 1) return n;
let count = 1;
let ans = 1;
for (let i = 0; i < n - 1; i++) {
nums[i + 1] > nums[i] ? count ++ : (count = 1);
ans = Math.max(ans, count);
}
return ans;
};

function findLengthOfLCIS(nums: number[]): number {
// 获取长度
const n = nums.length;
if (n <= 1) return n;
// 定义记录结果的变量
let count: number = 0;
// 定义dp数组并初始化为1
let dp: number[] = new Array(n).fill(1);
// 遍历
for (let i = 1; i < n; i++) {
if (nums[i - 1] < nums[i]) {
// 状态转移方程: 不连续递增子序列的跟前 0-i 个状态有关，连续递增的子序列只跟前一个状态有关
dp[i] = dp[i - 1] + 1;
}
// 记录dp数组中的最大值
if (count < dp[i]) count = dp[i];
}
return count;
}
