dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i]
}
return Math.min(dp[cost.length - 1], dp[cost.length - 2])
};

function minCostClimbingStairs(cost: number[]): number {
const n = cost.length;
let prev = 0, curr = 0;
for (let i = 2; i <= n; i++) {
let next = Math.min(curr + cost[i - 1], prev + cost[i - 2]);
prev = curr;
curr = next;
}
return curr;
}

function minCostClimbingStairs(cost: number[]): number {
const size = cost.length;
if (size === 0) return 0;
if (size === 1) return cost[0];
const minCost: number[] = new Array(size).fill(0);
minCost[0] = cost[0];
minCost[1] = cost[1];
for (let i = 2; i < size; i++) {
minCost[i] = Math.min(minCost[i - 1], minCost[i - 2]) + cost[i];
}
// The minimum cost to reach the top can be from either of the last two steps
return Math.min(minCost[size - 1], minCost[size - 2]);
}

function customSortString(order: string, s: string): string {
// 创建一个数组来存储每个字符的优先级值
const val: number[] = new Array(26).fill(0);
// 根据 `order` 字符串设置每个字符的优先级值
for (let i = 0; i < order.length; ++i) {
const charCode = order[i].charCodeAt(0) - 'a'.charCodeAt(0);
val[charCode] = i + 1;
}
// 将字符串 `s` 转换为字符数组
const arr: string[] = Array.from(s);
// 按照 `val` 数组中的优先级对字符数组进行排序
arr.sort((c0, c1) => {
const index0 = c0.charCodeAt(0) - 'a'.charCodeAt(0);
const index1 = c1.charCodeAt(0) - 'a'.charCodeAt(0);
return val[index0] - val[index1];
});
// 将排序后的字符数组拼接成字符串并返回
return arr.join('');
}

function customSortString(order: string, s: string): string {
// 创建一个数组来存储每个字符的频率
const freq: number[] = new Array(26).fill(0);
// 统计字符串 `s` 中每个字符的出现次数
for (let i = 0; i < s.length; ++i) {
const ch: string = s[i];
freq[ch.charCodeAt(0) - 'a'.charCodeAt(0)]++;
}
let ans: string = '';
// 根据 `order` 字符串中的顺序构建结果字符串
for (let i = 0; i < order.length; ++i) {
const ch: string = order[i];
while (freq[ch.charCodeAt(0) - 'a'.charCodeAt(0)] > 0) {
ans += ch;
freq[ch.charCodeAt(0) - 'a'.charCodeAt(0)]--;
}
}
// 将剩余的字符（不在 `order` 中的字符）添加到结果字符串中
for (let i = 0; i < 26; ++i) {
while (freq[i] > 0) {
ans += String.fromCharCode(i + 'a'.charCodeAt(0));
freq[i]--;
}
}
return ans;
}
