function lemonadeChange(bills: number[]): boolean {
// 表示自己的钱箱（用于存储零钱）
const box: number[] = [];
// 判断是否有顾客还在
while (bills.length) {
// 取出当前排在最前面顾客的钱
const money: number = bills.shift();
// 这种情况不需要找零
if (money === 5) {
box.push(money);
} else {
// 手里的零钱要降序排列也就说最大的面值的钱放在最前面
box.sort((a, b) => b - a);
// 顾客的钱减去饮料的钱就是需要找给顾客的零钱
let change = money - 5;
for (let i = 0, len = box.length; i < len; i++) {
if (box[i] <= change) {
change -= box[i];
box.splice(i, 1);
// 删除了元素，数组的长度发生了变化，要维持刚才的i不变
i--;
}
if (change === 0) break;
}
// 没有足够的零钱找给顾客
if (change !== 0) return false;
// 顾客的钱存起来
box.push(money);
}
}
return true;
};
这种贪心策略，没有任何技巧
这种算法耗时很严重，时间复杂度 O(n2lognn^2logn)
上面这种思路就很复杂了，不推荐这种算法

function lemonadeChange(bills: number[]): boolean {
// 准备 5元，10元面值的钱，用于标识是否有对应的零钱
let five: number = 0, ten: number = 0;
// 遍历所有的客户付款
for (const bill of bills) {
// 匹配客户付款5元的场景: 不用找零
if (bill === 5) {
five += 1;
// 匹配客户付款10元的场景: 找零5元，进账10元
} else if (bill === 10) {
if (five === 0) return false;
five -= 1;
ten += 1;
// 匹配客户付款20元的场景: 找零15，进账20(不用处理, 这20元无法用于找零), 有两种情况
} else {
// 情况1: 5元和10元的组合
if (five > 0 && ten > 0) {
five -= 1;
ten -= 1;
// 情况2: 没有10元的情况下, 使用三张5元的
} else if (five >= 3) {
five -= 3;
// 否则找零失败，返回 false
} else return false;
}
}
return true;
};
这种是官方提供思路
由于顾客只可能给你三个面值的钞票，而且我们一开始没有任何钞票
因此我们拥有的钞票面值只可能是 5 美元，10 美元和 20 美元三种
我们所能找零的面值也就只有 5 美元 和 10美元 两种面值的组合
基于分类讨论的方式，列举了可能得找零场景，一个循环就搞定
时间复杂度：O(N)，其中 N 是 bills 的长度
空间复杂度：O(1)，常数空间，只用了2个变量，所以是O(1)
备注: O(2)也用O(1)来表示，常数都是O(1)

/**
* Definition for singly-linked list.
* class ListNode {
* val: number
* next: ListNode | null
* constructor(val?: number, next?: ListNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.next = (next===undefined ? null : next)
* }
* }
*/
function middleNode(head: ListNode | null): ListNode | null {
const A = [head];
while (A[A.length - 1].next)
A.push(A[A.length - 1].next);
return A[Math.trunc(A.length / 2)];
};

/**
* Definition for singly-linked list.
* class ListNode {
* val: number
* next: ListNode | null
* constructor(val?: number, next?: ListNode | null) {
* this.val = (val===undefined ? 0 : val)
* this.next = (next===undefined ? null : next)
* }
* }
*/
function middleNode(head: ListNode | null): ListNode | null {
let n = 0;
let cur = head;
while (cur) {
++n;
cur = cur.next;
}
let k = 0;
cur = head;
while (k < Math.trunc(n / 2)) {
++k;
cur = cur.next;
}
return cur;
};

function stoneGame(piles: number[]): boolean {
const length = piles.length;
const dp = new Array(length).fill(0).map(() => new Array(length).fill(0));
for (let i = 0; i < length; i++) {
dp[i][i] = piles[i];
}
for (let i = length - 2; i >= 0; i--) {
for (let j = i + 1; j < length; j++) {
dp[i][j] = Math.max(piles[i] - dp[i + 1][j], piles[j] - dp[i][j - 1]);
}
}
return dp[0][length - 1] > 0;
};

function stoneGame(piles: number[]): boolean {
const length = piles.length;
const dp = new Array(length).fill(0);
for (let i = 0; i < length; i++) {
dp[i] = piles[i];
}
for (let i = length - 2; i >= 0; i--) {
for (let j = i + 1; j < length; j++) {
dp[j] = Math.max(piles[i] - dp[j], piles[j] - dp[j - 1]);
}
}
return dp[length - 1] > 0;
};

function sortArrayByParity(nums: number[]): number[] {
const n: number = nums.length;
let index: number = 0;
const res: number[] = new Array(n).fill(0);
// 第一次遍历，将偶数放入结果数组
for (const num of nums) {
if (num % 2 === 0) {
res[index++] = num;
}
}
// 第二次遍历，将奇数放入结果数组
for (const num of nums) {
if (num % 2 === 1) {
res[index++] = num;
}
}
return res;
}

function sortArrayByParity(nums: number[]): number[] {
const n = nums.length;
const res = new Array(n).fill(0);
let left = 0, right = n - 1;
for (const num of nums) {
if (num % 2 === 0) {
res[left++] = num;
} else {
res[right--] = num;
}
}
return res;
};

function sortArrayByParity(nums: number[]): number[] {
let left = 0, right = nums.length - 1;
while (left < right) {
while (left < right && nums[left] % 2 === 0) {
left++;
}
while (left < right && nums[right] % 2 === 1) {
right--;
}
if (left < right) {
const temp = nums[left];
nums[left] = nums[right];
nums[right] = temp;
left++;
right--;
}
}
return nums;
};
