function minFlipsMonoIncr(s: string): number {
const n = s.length;
let dp0 = 0, dp1 = 0;
for (let i = 0; i < n; i++) {
const c = s[i];
let dp0New = dp0, dp1New = Math.min(dp0, dp1);
if (c === '1') {
dp0New++;
} else {
dp1New++;
}
dp0 = dp0New;
dp1 = dp1New;
}
return Math.min(dp0, dp1);
};

function minFlipsMonoIncr(s: string): number {
let one = 0;
let dp = 0;
for (let i = 0; i < s.length; i++) {
const c = s.charAt(i);
if (c === '0') {
// 当前等于 0 ，看反转前面全是 1 的为 0 和 反转当前为 1 的代价哪个小
dp = Math.min(one, dp + 1);
} else {
// 记录前面为 1 的个数
++one;
}
}
return dp;
}
