function longestArithSeqLength(nums: number[]): number {
const minv = Math.min(...nums);
const maxv = Math.max(...nums);
const diff = maxv - minv;
let ans = 1;
for (let d = -diff; d <= diff; ++d) {
const f = new Array(maxv + 1).fill(-1);
for (const num of nums) {
let prev = num - d;
if (prev >= minv && prev <= maxv && f[prev] !== -1) {
f[num] = Math.max(f[num], f[prev] + 1);
ans = Math.max(ans, f[num]);
}
f[num] = Math.max(f[num], 1);
}
}
return ans;
};

function longestArithSeqLength(nums: number[]): number {
const mp = new Map<number, number>();
const n = nums.length;
const dp: number[][] = Array.from({ length: n }, () => Array(n).fill(2));
let ans = 0;
for (let i = 0; i < n; i++) {
for (let j = i + 1; j < n; j++) {
const target = 2 * nums[i] - nums[j];
if (mp.has(target)) {
dp[i][j] = (dp[mp.get(target)!][i] || 2) + 1;
}
ans = Math.max(ans, dp[i][j]);
}
mp.set(nums[i], i);
}
return ans;
}
