class Foo {
private firstJobDone: boolean = false;
private secondJobDone: boolean = false;
constructor() {}
// 第一个任务，不需要等待任何其他任务完成
public async first(printFirst: () => void) {
// 执行第一个任务
printFirst();
// 标记第一个任务已完成
this.firstJobDone = true;
}
// 第二个任务，需要等待第一个任务完成
public async second(printSecond: () => void) {
// 等待第一个任务完成
while (!this.firstJobDone) {
await new Promise(resolve => setTimeout(resolve, 1)); // 简单的轮询等待
}
// 执行第二个任务
printSecond();
// 标记第二个任务已完成
this.secondJobDone = true;
}
// 第三个任务，需要等待第二个任务完成
public async third(printThird: () => void) {
// 等待第二个任务完成
while (!this.secondJobDone) {
await new Promise(resolve => setTimeout(resolve, 1)); // 简单的轮询等待
}
// 执行第三个任务
printThird();
}
}
