function diagonalSort(mat: number[][]): number[][] {
const n: number = mat.length;
const m: number = mat[0].length;
const diag: number[][] = new Array(m + n).fill([]).map(() => [] as number[]);
// 将矩阵中的每个元素放入对应的对角线数组中
for (let i = 0; i < n; i++) {
for (let j = 0; j < m; j++) {
diag[i - j + m].push(mat[i][j]);
}
}
// 对每个对角线数组进行排序（降序）
diag.forEach(d => d.sort((a, b) => b - a));
// 将排序后的元素放回原矩阵中
for (let i = 0; i < n; i++) {
for (let j = 0; j < m; j++) {
mat[i][j] = diag[i - j + m].pop()!;
}
}
return mat;
}

function diagonalSort(mat: number[][]): number[][] {
const m = mat.length;
const n = mat[0].length;
for (let k = 1 - n; k < m; k++) {
// k = i - j
const left_i = Math.max(k, 0);
const right_i = Math.min(k + n, m);
const a = [];
for (let i = left_i; i < right_i; i++) {
a.push(mat[i][i - k]);
}
a.sort((a, b) => a - b);
for (let i = left_i; i < right_i; i++) {
mat[i][i - k] = a[i - left_i];
}
}
return mat;
};
