function onesCount(x: number): number {
let c = 0;
while (x > 0) {
c += x % 2;
x = Math.floor(x / 2);
}
return c;
}
function sortByBits(arr: number[]): number[] {
arr.sort((a, b) => {
const cx = onesCount(a);
const cy = onesCount(b);
if (cx === cy) {
return a - b; // 如果1的数量相同，则按数值大小排序
}
return cx - cy; // 否则按1的数量排序
});
return arr;
}

function sortByBits(arr: number[]): number[] {
// 计算每个数的二进制中 1 的个数
const bit: number[] = new Array(10001).fill(0);
for (let i = 1; i <= 10000; ++i) {
bit[i] = bit[i >> 1] + (i & 1);
}
// 深拷贝数组以避免原地修改
const sortedArr = [...arr];
// 使用自定义排序函数进行排序
sortedArr.sort((x, y) => {
if (bit[x] < bit[y]) {
return -1;
}
if (bit[x] > bit[y]) {
return 1;
}
return x - y;
});
return sortedArr;
}
