function minNumberOfSemesters(n: number, relations: number[][], k: number): number {
const pre1: number[] = new Array(n).fill(0);
for (const r of relations) {
pre1[r[1] - 1] |= 1 << (r[0] - 1); // r[1] 的先修课程集合，下标改从 0 开始
}
const u = (1 << n) - 1; // 全集
const memo: number[] = new Array(1 << n).fill(-1); // -1 表示没有计算过
const dfs = (i: number): number => {
if (i === 0) { // 空集
return 0;
}
if (memo[i] !== -1) { // 之前算过了
return memo[i];
}
let res = Infinity;
const ci = u ^ i; // i 的补集
let i1 = 0;
for (let j = 0; j < n; j++) {
const p = pre1[j];
if ((i >> j & 1) > 0 && (p | ci) === ci) { // p 在 i 的补集中，可以学（否则这学期一定不能学）
i1 |= 1 << j;
}
}
if (countBits(i1) <= k) { // 如果个数小于 k，则可以全部学习，不再枚举子集
res = dfs(i ^ i1) + 1;
} else {
for (let j = i1; j > 0; j = (j - 1) & i1) { // 枚举 i1 的子集 j
if (countBits(j) === k) {
res = Math.min(res, dfs(i ^ j) + 1);
}
}
}
memo[i] = res; // 记忆化
return res;
};
return dfs(u);
}
