function getSumAbsoluteDifferences(nums: number[]): number[] {
const n = nums.length;
let leftSum = 0;
let rightSum = nums.reduce((acc, val) => acc + val, 0);
const result: number[] = new Array(n);
for (let i = 0; i < n; i++) {
rightSum -= nums[i];
result[i] = i * nums[i] - leftSum + rightSum - (n - i - 1) * nums[i];
leftSum += nums[i];
}
return result;
}

