st2.pop();
}
let pos = st1.length - 1;
while (pos >= 0 && nums[st1[pos]] < v) {
pos--;
}
st2.push(...st1.slice(pos + 1, st1.length));
st1.splice(pos + 1);
st1.push(i);
}
